package workshop.vfx.paper.m8;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static workshop.vfx.paper.m8.K1Fixture.*;
import workshop.vfx.delivery.*;
import workshop.vfx.math.core.*;
import workshop.vfx.scene.*;

class K1GeometryTest {
    // Independent polynomial/tick formula, not the production Motion/Timing implementation.
    static double sway(long age) { double phase=age%60;double t=(phase<=30?phase:60-phase)/30;return Math.toRadians(-8+16*t*t*(3-2*t)); }

    @Test void exactTierTotalsAndReservations(){int[] n={8,18,24};for(var tier:QualityTier.values()){var f=new K1Fixture();f.start(tier);var d=f.draft(A);assertEquals(n[tier.ordinal()],frame(d).pointCount());assertEquals(n[tier.ordinal()],d.recipe().variant(tier).maxPointsPerFrame());}}
    @Test void paletteAndRolesAreExact(){var r=AuraRecipe.create(1200);assertEquals(EffectPriority.NORMAL,r.priority());assertEquals(LayerRole.ESSENTIAL,r.role("orbit"));assertEquals(LayerRole.STANDARD,r.role("halo"));var f=new K1Fixture();f.balanced();var b=frame(f.draft(A)).batches();assertEquals(workshop.vfx.paper.core.DemoStyleCatalog.END_ROD,b.get(0).style());assertEquals(M8StyleCatalog.CYAN_HALO,b.get(1).style());}
    @Test void bothLayersMatchIndependentFormulaAtAllTiersAndBoundaryTicks(){
        for(var tier:QualityTier.values()){var f=new K1Fixture();f.start(tier);for(long age:new long[]{0,1,15,30,59,60,79,80,123,1199}){
            f.tick=100+age;double[] p=f.position.get(A);p[0]=0.28*age;p[1]=64+Math.sin(age/5.0);p[2]=-0.1*age;p[3]=(float)(age*3.0);
            var fr=frame(f.draft(A));for(var b:fr.batches()){boolean orbit=b.layer().equals("orbit");double r=orbit?0.9:0.45,h=orbit?1:2.15;double span=Math.toRadians(tier==QualityTier.SIMPLE?120:tier==QualityTier.BALANCED?160:200);double spin=orbit?sway(age):-2*Math.PI*(age%80)/80;
                for(int i=0;i<b.size();i++){double base=orbit?Math.PI/2-span/2+span*i/(b.size()-1):2*Math.PI*i/b.size();double angle=base+spin-Math.toRadians((float)p[3]);Vec3 expected=new Vec3(p[0]+r*Math.cos(angle),p[1]+h,p[2]-r*Math.sin(angle));assertTrue(b.point(i).sub(expected).length()<1e-9,"tier="+tier+" age="+age+" layer="+b.layer()+" i="+i);}
            }
        }}
    }
    @Test void waistAndHaloRadiiHeightsAndNoSeamDuplicate(){var f=new K1Fixture();f.balanced();for(var b:frame(f.draft(A)).batches()){double r=b.layer().equals("orbit")?0.9:0.45,h=b.layer().equals("orbit")?65:66.15;for(int i=0;i<b.size();i++){assertEquals(r,Math.hypot(b.x(i),b.z(i)),1e-12);assertEquals(h,b.y(i),1e-12);}assertTrue(b.point(0).sub(b.point(b.size()-1)).length()>0.1);}}
    @Test void rearSwayAndHaloSpinKeepTheirIndependentPeriods(){var f=new K1Fixture();f.balanced();var zero=frame(f.draft(A));f.tick=130;var turn=frame(f.draft(A));assertTrue(turn.batches().get(0).point(0).sub(zero.batches().get(0).point(0)).length()>0.1);f.tick=101;assertTrue(frame(f.draft(A)).batches().get(1).z(0)>0);f.tick=160;assertTrue(frame(f.draft(A)).batches().get(0).point(0).sub(zero.batches().get(0).point(0)).length()<1e-12);f.tick=180;assertTrue(frame(f.draft(A)).batches().get(1).point(0).sub(zero.batches().get(1).point(0)).length()<1e-12);}
    @Test void yawMapsForwardLeftAndUp(){for(float yaw:new float[]{0,45,90,180,270,-90,359.5f,720,-1234.25f}){var f=new K1Fixture();f.position.get(A)[3]=yaw;f.balanced();var q=f.draft(A).anchor().rotation();double r=Math.toRadians(yaw);assertTrue(q.rotate(Vec3.Z).sub(new Vec3(-Math.sin(r),0,Math.cos(r))).length()<1e-12);assertTrue(q.rotate(Vec3.X).sub(new Vec3(Math.cos(r),0,Math.sin(r))).length()<1e-12);assertTrue(q.rotate(Vec3.Y).sub(Vec3.Y).length()<1e-12);}}
    @Test void headYawAndPitchDoNotTiltOrRotateAttachment(){var f=new K1Fixture();f.balanced();var expected=frame(f.draft(A));for(double pitch:new double[]{-90,90,0,Float.NaN}){f.position.get(A)[4]=127;f.position.get(A)[5]=pitch;var actual=frame(f.draft(A));for(int b=0;b<expected.batches().size();b++)assertArrayEquals(expected.batches().get(b).coordinates(),actual.batches().get(b).coordinates());}}
    @Test void walkingSprintingJumpingAndFallingHaveExactCentres(){var f=new K1Fixture();f.balanced();for(int i=0;i<100;i++){f.tick++;double[] p=f.position.get(A);p[0]+=i<50?0.22:0.28;p[1]=64+2*Math.sin(i/10.0);p[2]+=0.1;p[3]=i*7;var fr=frame(f.draft(A));for(var b:fr.batches()){double sx=0,sz=0;for(int j=0;j<b.size();j++){sx+=b.x(j);sz+=b.z(j);}double cx=p[0],cz=p[2];if(b.layer().equals("orbit")){double step=Math.toRadians(160)/(b.size()-1);double meanRadius=0.9*Math.sin(b.size()*step/2)/(b.size()*Math.sin(step/2));double centre=Math.PI/2+sway(f.tick-100)-Math.toRadians((float)p[3]);cx+=meanRadius*Math.cos(centre);cz-=meanRadius*Math.sin(centre);}assertEquals(cx,sx/b.size(),1e-10);assertEquals(cz,sz/b.size(),1e-10);assertEquals(p[1]+(b.layer().equals("orbit")?1:2.15),b.y(0),1e-10);}}}
    @Test void worldChangeContinuesWithSameRecipeClockAndNoInterpolatedPoints(){var f=new K1Fixture();f.balanced();var first=f.draft(A);f.worlds.put(A,W2);f.position.put(A,new double[]{10000,80,-3000,90,0,0});f.tick=223;var next=f.draft(A);assertEquals(first.requestId(),next.requestId());assertSame(first.recipe(),next.recipe());assertEquals(123,next.frameOrdinal());assertEquals(f.ids.worldId(W2),next.worldId());for(var b:frame(next).batches())for(int i=0;i<b.size();i++){assertTrue(Math.abs(b.x(i)-10000)<=0.901);assertTrue(Math.abs(b.z(i)+3000)<=0.901);}}
    @Test void sceneAndShapesAreReusedAcrossFramesOwnersAndReplacement(){var f=new K1Fixture();f.balanced();var one=f.draft(A);f.auras.start(B,QualityTier.HEAVY,f.tick);assertSame(one.recipe(),f.draft(B).recipe());var shape=one.recipe().variant(QualityTier.BALANCED).layers().get(0).shape();for(int i=0;i<60;i++){f.tick++;var d=f.draft(A);assertSame(one.recipe(),d.recipe());assertSame(shape,d.recipe().variant(d.tier()).layers().get(0).shape());}f.start(QualityTier.SIMPLE);assertSame(one.recipe(),f.draft(A).recipe());}
    @Test void deterministicFrameHasNoHiddenClockOrRandomInput(){var f=new K1Fixture();f.balanced();f.tick=321;var a=frame(f.draft(A));var b=frame(f.draft(A));assertEquals(a.localTicks(),b.localTicks());for(int i=0;i<a.batches().size();i++)assertArrayEquals(a.batches().get(i).coordinates(),b.batches().get(i).coordinates());}
    @Test void recipeLifetimeBoundsRejectWithoutClamping(){for(int n:new int[]{-1,0,19,12001,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->AuraRecipe.create(n));assertNotNull(AuraRecipe.create(20));assertNotNull(AuraRecipe.create(12000));}
}
